#!/bin/bash
set -euo pipefail

awk 'NF {
    ip = $1
    count[ip]++
    if (!(ip in order)) {
        order[ip] = ++n
    }
}
END {
    for (ip in count) {
        printf "%d\t%d\t%s\n", count[ip], order[ip], ip
    }
}' access.log |
sort -t $'\t' -k1,1nr -k2,2n |
head -n 3 |
cut -f3
